// @generated by:gauntlet run:godseye-local-recovery
import { randomBytes, randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION, ProjectResponse } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { RecoveryOverview } from "../packages/contracts/src/recovery.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";
import { recoveryPolicy } from "./recovery-helpers.js";

describe("strict authenticated owner recovery HTTP and typed client", () => {
  let fixture: OwnerAuthFixture,
    infrastructure: InfrastructureEngine,
    app: ReturnType<typeof createApp>,
    headers: Headers;
  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    infrastructure = new InfrastructureEngine(fixture.store);
    app = createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      infrastructure.foundation,
      undefined,
      infrastructure,
    );
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => {
    await fixture.close();
  });
  function request(path: string, method = "GET", body?: unknown, key = randomUUID()) {
    const selected = new Headers(headers);
    if (method !== "GET") selected.set("idempotency-key", key);
    return app.request(new URL(`/api/v1${path}`, fixture.origin), {
      method,
      headers: selected,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  }
  async function backupInput() {
    const saved = ProjectResponse.parse(
      await (await request("/projects", "POST", projectInput)).json(),
    );
    const environment = saved.environments[0];
    if (!environment) throw new Error("Owner recovery source environment missing");
    return {
      projectId: saved.id,
      environmentId: environment.id,
      sourceAllocationId: randomUUID(),
      expectedProjectRevision: saved.revision,
      expectedEnvironmentRevision: environment.revision,
      kind: "full",
      policy: recoveryPolicy,
    };
  }

  it("T-AC-42 authenticates every recovery route before interpreting its body", async () => {
    for (const [method, path] of [
      ["GET", "/recovery"],
      ["POST", "/recovery/backups/preparations"],
      ["POST", "/recovery/restores/preparations"],
      ["POST", "/recovery/archives/preparations"],
      ["POST", "/recovery/admissions"],
      ["GET", `/recovery/environments/${randomUUID()}/activation`],
    ]) {
      const response = await app.request(new URL(`/api/v1${path}`, fixture.origin), {
        method,
        headers: fixture.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-39 T-AC-42 exposes unconfigured physical execution, blocked activation and prepared-only scheduling", async () => {
    const response = await request("/recovery");
    expect(response.status).toBe(200);
    expect(RecoveryOverview.parse(await response.json())).toEqual({
      execution: "unconfigured",
      activation: "blocked",
      schedule: "prepared-only",
      preparations: [],
      backups: [],
      runs: [],
    });
  });

  it("T-AC-42 rejects stale passkey authority for backup, restore and admission", async () => {
    const input = await backupInput();
    headers = (await fixture.session(6 * 60_000)).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
    for (const [path, body] of [
      ["/recovery/backups/preparations", input],
      [
        "/recovery/restores/preparations",
        {
          projectId: input.projectId,
          sourceEnvironmentId: input.environmentId,
          backupId: randomUUID(),
          expectedProjectRevision: input.expectedProjectRevision,
          expectedEnvironmentRevision: input.expectedEnvironmentRevision,
          targetTime: "2026-11-11T11:30:00.000Z",
          name: "new-recovery",
        },
      ],
      ["/recovery/admissions", { preparationId: randomUUID(), expectedHash: "a".repeat(64) }],
    ] as const) {
      const response = await request(path, "POST", body);
      expect(response.status).toBe(403);
      expect(await response.json()).toMatchObject({ error: { code: "STEP_UP_REQUIRED" } });
    }
  });

  it.each(["sql", "repositoryId", "stanza", "path", "providerId", "material", "archiveCommand"])(
    "T-AC-35 T-AC-42 rejects injected %s without reflecting caller material",
    async (field) => {
      const input = await backupInput(),
        marker = randomBytes(32).toString("base64url");
      const response = await request("/recovery/backups/preparations", "POST", {
        ...input,
        [field]: marker,
      });
      expect(response.status).toBe(422);
      expect(await response.text()).not.toContain(marker);
      expect(
        RecoveryOverview.parse(await (await request("/recovery")).json()).preparations,
      ).toEqual([]);
    },
  );

  it("T-AC-42 requires a mutation key before attempting a physical-source lookup", async () => {
    const response = await app.request(
      new URL("/api/v1/recovery/backups/preparations", fixture.origin),
      { method: "POST", headers, body: JSON.stringify(await backupInput()) },
    );
    expect(response.status).toBe(400);
    expect(await response.json()).toMatchObject({ error: { code: "INVALID_IDEMPOTENCY_KEY" } });
  });

  it("T-AC-42 rejects unexpected producer material at the response boundary", async () => {
    const marker = randomBytes(32).toString("base64url"),
      original = infrastructure.recovery.overview.bind(infrastructure.recovery);
    infrastructure.recovery.overview = async (actor) => ({
      ...(await original(actor)),
      privateMaterial: marker,
    });
    const response = await request("/recovery"),
      body = await response.text();
    expect(response.status).toBe(500);
    expect(body).not.toContain(marker);
    expect(body.length).toBeLessThan(1024);
    expect(JSON.parse(body)).toMatchObject({ error: { code: "INTERNAL_ERROR" } });
  });

  it("T-AC-42 uses the typed client against real routes and rejects missing keys locally", async () => {
    const client = createControlClient({
      baseUrl: `${fixture.origin}/api/v1`,
      headers,
      fetch: async (input, init) => app.request(new Request(input, init)),
    });
    expect(await client.recoveryOverview()).toMatchObject({
      execution: "unconfigured",
      activation: "blocked",
      schedule: "prepared-only",
    });
    await expect(
      client.admitRecovery({ preparationId: randomUUID(), expectedHash: "a".repeat(64) }, ""),
    ).rejects.toThrow(/idempotency/i);
  });

  it("T-AC-42 publishes strict recovery commands without destructive or activation shortcuts", async () => {
    const document = await (await request("/openapi.json")).json();
    for (const path of [
      "/api/v1/recovery/backups/preparations",
      "/api/v1/recovery/restores/preparations",
      "/api/v1/recovery/archives/preparations",
      "/api/v1/recovery/admissions",
    ]) {
      expect(document.paths[path].post.parameters).toEqual(
        expect.arrayContaining([
          expect.objectContaining({
            name: expect.stringMatching(/^idempotency-key$/i),
            required: true,
          }),
        ]),
      );
      expect(
        document.paths[path].post.requestBody.content["application/json"].schema
          .additionalProperties,
      ).toBe(false);
    }
    for (const action of ["expire", "purge", "activate", "promote", "overwrite"]) {
      const response = await request(`/recovery/${action}`, "POST", {});
      expect(response.status).toBe(404);
    }
  });
});
